<div id="kt_content_container" class="container-xxl py-5"><div class="d-flex flex-wrap flex-stack mb-7"><div><h1 class="fw-bold text-gray-900 mb-2">Dashboard / Estadísticas de Ventas</h1><div class="text-muted fs-6">Resumen de ventas y pedidos de la tienda</div></div></div><div class="row g-5 mb-7"><div class="col-md-3"><div class="card card-flush"><div class="card-body"><span class="text-muted">Ventas confirmadas</span><h2 id="ventas_total">$0.00</h2></div></div></div><div class="col-md-3"><div class="card card-flush"><div class="card-body"><span class="text-muted">Pedidos pendientes</span><h2 id="pedidos_pendientes">0</h2></div></div></div><div class="col-md-3"><div class="card card-flush"><div class="card-body"><span class="text-muted">Pagados / enviados</span><h2 id="pedidos_enviados">0</h2></div></div></div><div class="col-md-3"><div class="card card-flush"><div class="card-body"><span class="text-muted">Entregados</span><h2 id="pedidos_entregados">0</h2></div></div></div></div><div class="card card-flush"><div class="card-header"><h3 class="card-title fw-bold">Resumen de pedidos</h3></div><div class="card-body"><table class="table align-middle table-row-dashed" id="tabla_estadisticas_ventas"><thead><tr><th>Pedido</th><th>Cliente</th><th>Fecha</th><th>Total</th><th>Estatus</th></tr></thead><tbody></tbody></table></div></div></div>
<script>(function(){fetch('actions/16.read_pedidos.php').then(r=>r.json()).then(res=>{const pedidos=res.data||[],validos=pedidos.filter(p=>Number(p.estatus)!==4);document.getElementById('ventas_total').textContent='$'+validos.reduce((s,p)=>s+Number(p.total||0),0).toFixed(2);document.getElementById('pedidos_pendientes').textContent=pedidos.filter(p=>Number(p.estatus)===1).length;document.getElementById('pedidos_enviados').textContent=pedidos.filter(p=>Number(p.estatus)===2).length;document.getElementById('pedidos_entregados').textContent=pedidos.filter(p=>Number(p.estatus)===3).length;const estados={1:'Pendiente',2:'Pagado / Enviado',3:'Entregado',4:'Cancelado'};$('#tabla_estadisticas_ventas').DataTable({data:pedidos.map(p=>['#'+p.id_pedido,p.usuario_nombre,p.fecha_pedido,'$'+Number(p.total).toFixed(2),estados[p.estatus]||'Desconocido']),columns:[{title:'Pedido'},{title:'Cliente'},{title:'Fecha'},{title:'Total'},{title:'Estatus'}],pageLength:10,language:{url:'https://cdn.datatables.net/plug-ins/1.13.7/i18n/es-ES.json'}});});})();</script>
